{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "Donepezil, which shares the dimethoxybenzene and basic amine motifs, has an absolute oral bioavailability of 100% in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Valbenazine, a tetrabenazine-related VMAT2 inhibitor with a dimethoxybenzene and basic amine, has an absolute oral bioavailability of approximately 49% in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Urapidil, containing a dimethoxyphenyl group and a basic amine, has an absolute oral bioavailability of 78% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C63"],
      "claim": "Gallopamil, a verapamil analog with two dimethoxyphenyl groups and a tertiary amine, has a reported oral bioavailability of 96.3% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Tetrabenazine, the closest Morgan analogue, has very low oral systemic availability (~5%) in patients, but its low F is driven by rapid ketone reduction, a liability absent in the query's lactam.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C62"],
      "claim": "Almorexant, a large lipophilic dimethoxyisoquinoline amide, has an absolute oral bioavailability of ~11%, indicating that large lipophilic amides can have low F.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a lipophilic bis-dimethoxy benzazepinone with a tertiary amine side chain. Although the closest analogue tetrabenazine has very low F, its mechanism (ketone reduction) is not applicable to the query's lactam. Multiple structurally relevant analogues with dimethoxybenzene and basic amine motifs (donepezil, valbenazine, urapidil, gallopamil) show F >= 30-100%, and verapamil-like scaffolds cluster around 20-30%. The weight of transferable evidence supports F >= 20%.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the exact query scaffold.",
    "Tetrabenazine's low F is mechanistically tied to a ketone that the query lacks, limiting transfer.",
    "Enantiomer-specific first-pass metabolism, as seen with verapamil, is unknown for the query's stereocenter.",
    "The effect of the lactam versus ketone/amide on first-pass metabolism is not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

